/* :host is the real trigger <button> (button[ngptDropdownPill]) — the menu content lives in an
   `<ng-template>` that `[ngpMenuTrigger]` (hostDirectives, dropdown-pill.ts) portals and positions
   itself; this file owns only the trigger's own visual treatment. Composes pill-button's default
   variant inline (not via `<button ngptPillButton>`) so the host directive lands on a real button
   (docs/decisions.md). */
:host {
  display: inline-flex;
  align-items: center;
  gap: var(--ngpt-sys-space-150);
  white-space: nowrap; /* spec: label + chevron must render on one line */
  font: var(--ngpt-sys-typescale-label-large-medium);
  padding: var(--ngpt-sys-space-150) var(--ngpt-sys-space-300);
  border-radius: var(--ngpt-sys-shape-corner-large);
  border: 1px solid var(--ngpt-comp-pill-border-default);
  background: transparent;
  color: var(--ngpt-text-tertiary);
  cursor: pointer;
}

:host(:hover) {
  border-color: var(--ngpt-comp-pill-border-hover);
  background: var(--ngpt-bg-hover);
}

/* Focus state (real DOM focus still on the trigger button) and Open state (front-matter `states`
   list — DOM focus moves into the portaled menu's roving-tabindex options once open, so
   :focus-visible alone can't carry this) share the same accent-border / white-text treatment. */
:host(:focus-visible),
:host([data-open]) {
  border-color: var(--ngpt-accent);
  color: var(--ngpt-text-primary);
  box-shadow: 0 0 0 2px var(--ngpt-focus-ring);
  outline: none;
}

