import { ChangeDetectionStrategy, Component, ViewEncapsulation, input } from '@angular/core';
import type { ProseMeasure } from './prose.types';

/**
 * Typographic layer for arbitrary projected article markup — headings, lists, blockquote, hr,
 * strong/em, and heading anchor links. Attribute-hosted (ADR-0005) on the consumer's own
 * `<article>` (a standalone doc page) or `<div>` (a prose run inside a larger section).
 *
 * The one `ViewEncapsulation.None` component in this build (CONVENTIONS.md #8) and it stays that
 * way after the attribute-host conversion: projected nodes carry the *declaring* component's
 * encapsulation id, so under emulated encapsulation no `:host h2` rule here could ever match
 * content delivered through `<ng-content>`. Changing the host element does not change that.
 * Because every rule is therefore global, the static `class: 'ngpt-prose'` below is what scopes
 * them — every selector in `prose.css` is written under `.ngpt-prose`. Neither is removable; see
 * docs/decisions.md § "Encapsulation and class scoping survive the conversion".
 *
 * Does not restyle inline `<code>`/`<a>` — consumers author `<ngpt-code-chip>` /
 * `<ngpt-inline-link>` directly inside the projected content instead. See docs/decisions.md.
 */
@Component({
  selector: 'article[ngptProse], div[ngptProse]',
  templateUrl: './prose.html',
  styleUrl: './prose.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    class: 'ngpt-prose',
    '[attr.data-measure]': 'measure()',
  },
})
export class Prose {
  readonly measure = input<ProseMeasure>('default');
}

styleUrlsData.data:
/* [ngptProse] — styles arbitrary projected article markup (headings, lists, blockquote, hr,
   strong/em, heading anchors). ViewEncapsulation.None (CONVENTIONS.md #8, ADR-0005): emulated
   encapsulation cannot reach projected content, so these rules are global — and the .ngpt-prose
   host class is what keeps them from leaking onto page content outside this component. Do NOT
   rewrite these selectors as :host — the component's own encapsulation id is not on the projected
   nodes. Every selector below must stay scoped under .ngpt-prose.

   No `display` rule: the host is the consumer's own <article>/<div>, already block-level. (The
   old ngpt-prose element host needed `display: block` because unknown elements default to inline.)

   Inline code and links are intentionally NOT restyled here — code-chip/inline-link are real
   components with their own encapsulation, authored directly inside projected content
   (<ngpt-code-chip>, <ngpt-inline-link>). See docs/decisions.md. */

/* ---------------------------------------------------------------------- */
/* Headings                                                                */
/* ---------------------------------------------------------------------- */

.ngpt-prose h1 {
  font: var(--ngpt-sys-typescale-headline-large);
  letter-spacing: -0.01em;
  color: var(--ngpt-text-primary);
  margin: 0 0 var(--ngpt-sys-space-350);
}

.ngpt-prose h2 {
  font: var(--ngpt-sys-typescale-title-large);
  color: var(--ngpt-text-primary);
  margin: var(--ngpt-sys-space-800) 0 var(--ngpt-sys-space-250);
}

.ngpt-prose h3 {
  font: var(--ngpt-sys-typescale-title-medium);
  color: var(--ngpt-text-primary);
  margin: var(--ngpt-sys-space-700) 0 var(--ngpt-sys-space-200);
}

.ngpt-prose h4 {
  font: var(--ngpt-sys-typescale-title-small);
  color: var(--ngpt-text-secondary);
  margin: var(--ngpt-sys-space-500) 0 var(--ngpt-sys-space-150);
}

/* data-measure="marketing" (Home's section H2s): headline-marketing weight/line-height/family,
   with the size overridden by the page's own clamp — the token's 36px is the clamp ceiling, not
   a fixed size, mirroring how the Home hero H1 layers a clamp on top of display-large. */
.ngpt-prose[data-measure='marketing'] h2 {
  font: var(--ngpt-sys-typescale-headline-marketing);
  font-size: clamp(26px, 3.4vw, 36px);
  letter-spacing: -0.02em;
}

.ngpt-prose :is(h2, h3, h4) {
  scroll-margin-top: var(--ngpt-sys-layout-scroll-offset);
}

/* ---------------------------------------------------------------------- */
/* Heading anchors — consumer-authored `<a class="heading-anchor">` inside */
/* the heading; prose styles the reveal-on-hover/focus treatment only.     */
/* ---------------------------------------------------------------------- */

.ngpt-prose .heading-anchor {
  margin-inline-start: var(--ngpt-sys-space-200);
  color: var(--ngpt-accent);
  text-decoration: none;
  opacity: 0;
  transition: opacity var(--ngpt-sys-motion-duration-fast) var(--ngpt-sys-motion-easing-standard);
}

.ngpt-prose :is(h2, h3, h4):hover .heading-anchor,
.ngpt-prose .heading-anchor:focus-visible {
  opacity: 1;
}

/* ---------------------------------------------------------------------- */
/* Lists                                                                    */
/* ---------------------------------------------------------------------- */

.ngpt-prose :is(ul, ol) {
  padding-inline-start: var(--ngpt-comp-list-indent);
  margin: 0 0 var(--ngpt-sys-space-600);
  font: var(--ngpt-sys-typescale-body-medium);
  color: var(--ngpt-text-tertiary);
}

.ngpt-prose li + li {
  margin-top: var(--ngpt-sys-space-150);
}

.ngpt-prose li::marker {
  color: var(--ngpt-text-muted);
}

.ngpt-prose ol {
  font-variant-numeric: tabular-nums;
}

.ngpt-prose :is(ul, ol) :is(ul, ol) {
  margin: var(--ngpt-sys-space-150) 0 0;
  padding-inline-start: var(--ngpt-sys-space-500);
}

/* ---------------------------------------------------------------------- */
/* Blockquote                                                               */
/* ---------------------------------------------------------------------- */

.ngpt-prose blockquote {
  border-inline-start: 2px solid var(--ngpt-border-strong);
  padding-inline-start: var(--ngpt-sys-space-400);
  margin: var(--ngpt-sys-space-600) 0;
  font: var(--ngpt-sys-typescale-body-medium);
  font-style: normal;
  color: var(--ngpt-text-tertiary);
}

/* ---------------------------------------------------------------------- */
/* Rule — visual treatment inferred (no Build spec table row); see          */
/* docs/decisions.md.                                                       */
/* ---------------------------------------------------------------------- */

.ngpt-prose hr {
  border: none;
  border-top: 1px solid var(--ngpt-border-subtle);
  margin: var(--ngpt-sys-space-600) 0;
}

/* ---------------------------------------------------------------------- */
/* Inline emphasis                                                          */
/* ---------------------------------------------------------------------- */

.ngpt-prose strong {
  color: var(--ngpt-text-secondary);
  font-weight: 600;
}

.ngpt-prose em {
  font-style: italic;
}

