import {
  ChangeDetectionStrategy,
  Component,
  TemplateRef,
  computed,
  input,
  output,
  viewChild,
} from '@angular/core';
import { NgIcon, provideIcons } from '@ng-icons/core';
import { lucideChevronDown } from '@ng-icons/lucide';
import { NgpMenuTrigger } from 'ng-primitives/menu';
import type { NgpOverlayTemplateContext } from 'ng-primitives/portal';
import { DropdownMenu } from '../dropdown-menu/dropdown-menu';
import type { DropdownMenuItem } from '../dropdown-menu/dropdown-menu.types';
import { withMenuTriggerPanel } from '../dropdown-menu/with-menu-trigger-panel';
import { withSelection } from './select-trigger.utils';

/**
 * Select-style menu-button trigger (spec: `docs/spec.md`). Host is the real `<button>` itself
 * (`button[ngptSelectTrigger]`) so `[ngpMenuTrigger]` (hostDirectives) lands `aria-haspopup` /
 * `aria-expanded` / `aria-controls` on the actual focusable element. No `role="combobox"` — the
 * popup it opens is `ngpt-dropdown-menu` (`role="menu"`), and ARIA's combobox contract requires
 * a listbox/tree/grid/dialog popup, so this follows the same Menu Button pattern as
 * `dropdown-pill` instead. See `docs/decisions.md`.
 */
@Component({
  selector: 'button[ngptSelectTrigger]',
  templateUrl: './select-trigger.html',
  styleUrl: './select-trigger.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [DropdownMenu, NgIcon],
  hostDirectives: [NgpMenuTrigger],
  viewProviders: [provideIcons({ lucideChevronDown })],
  host: {
    type: 'button',
    class: 'select-trigger',
    '[attr.data-open]': 'open() || null',
    '[attr.data-filled]': 'selectedLabel() ? "" : null',
  },
})
export class SelectTrigger {
  readonly items = input<readonly DropdownMenuItem[]>([]);
  readonly value = input<string>();
  readonly placeholder = input<string>('Select an option');

  readonly valueChange = output<string>();

  private readonly menu = viewChild.required<TemplateRef<NgpOverlayTemplateContext<unknown>>>('menu');

  protected readonly open = withMenuTriggerPanel(this.menu).open;

  protected readonly menuItems = computed<readonly DropdownMenuItem[]>(() =>
    withSelection(this.items(), this.value()),
  );

  protected readonly selectedLabel = computed<string | undefined>(
    () => this.items().find((option) => option.id === this.value())?.label,
  );

  protected onSelect(id: string): void {
    this.valueChange.emit(id);
  }
}

styleUrlsData.data:
/* :host is the real trigger <button> (button[ngptSelectTrigger]) — the option list lives in an
   `<ng-template>` that `[ngpMenuTrigger]` (hostDirectives, select-trigger.ts) portals and positions
   itself, so this file no longer anchors a child panel. */
:host {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ngpt-sys-space-250);
  width: 100%;
  padding: var(--ngpt-sys-space-275) var(--ngpt-comp-select-px);
  border-radius: var(--ngpt-sys-shape-corner-full);
  border: 1px solid var(--ngpt-comp-control-border-default);
  background: var(--ngpt-bg-raised);
  color: var(--ngpt-comp-select-placeholder);
  font-size: 14px;
  cursor: pointer;
  transition:
    border-color var(--ngpt-sys-motion-duration-base) var(--ngpt-sys-motion-easing-standard),
    color var(--ngpt-sys-motion-duration-base) var(--ngpt-sys-motion-easing-standard),
    box-shadow var(--ngpt-sys-motion-duration-base) var(--ngpt-sys-motion-easing-standard);
}

.select-trigger-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* "filled" state (spec front-matter) — a value is selected but the trigger is neither open nor
   focused. No dedicated token ships for this in the spec's Build spec table, so it reuses the
   same secondary-text tier the mock already applies to the active state (docs/decisions.md). */
:host([data-filled]) {
  color: var(--ngpt-text-secondary);
}

/* Active/focus state (spec states table). Keyed off the `data-open` host attribute per
   CONVENTIONS.md #3 (state as data-* attributes) rather than the mock's `.is-active` class or
   `[aria-expanded]` selector. `:focus-visible` is native browser state, not app state, so it's
   composed alongside rather than mirrored into a data attribute. */
:host([data-open]),
:host(:focus-visible) {
  border: 1.5px solid var(--ngpt-accent);
  box-shadow: 0 0 0 2px var(--ngpt-focus-ring);
  color: var(--ngpt-text-secondary);
  outline: none;
}

:host([data-open]) ng-icon,
:host(:focus-visible) ng-icon {
  color: var(--ngpt-accent);
}

